pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes == "ping" {
        return Ok(Msg::Ping);
    }

    if let Some(name) = bytes.strip_prefix("v:2|hello:") {
        return Ok(Msg::Hello(name.into()));
    }

    eprintln!("decode error: unknown message");
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(name) => format!("v:2|hello:{name}"),
    }
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    fn ping_encode_roundtrip() -> Msg {
        decode(&encode(&Msg::Ping)).unwrap()
    }

    #[test]
    fn ping_roundtrips_through_encoding() {
        assert!(matches!(ping_encode_roundtrip(), Msg::Ping));
    }

    #[test]
    fn hello_uses_the_v2_envelope() {
        let encoded = encode(&Msg::Hello("Ada".into()));
        assert_eq!(encoded, "v:2|hello:Ada");
        assert!(matches!(decode(&encoded), Ok(Msg::Hello(name)) if name == "Ada"));
    }

    #[test]
    fn versioned_hello_can_have_an_empty_name() {
        assert!(matches!(decode("v:2|hello:"), Ok(Msg::Hello(name)) if name.is_empty()));
    }
}

